// directorynote_golden_test.go — T-41: the generated-golden
// differential for the law sweep + the Website Directory.
//
// testdata/directorynote.golden.json is generated by
// testdiff/goldens/dump_directorynote.py from the unmodified reference
// (assadigit/GitCurator @ 98f4fc7, the pinned venv's CPython 3.12.15
// stdlib) with the directory clock frozen at 2026-10-17 12:00:00 — no
// per-run facts inside. The Go side reconstructs the generator's own
// fixture vaults, replays every section against this package's port,
// and byte-compares (the tempdir roots fold to <TMP> on both sides —
// the golden's paths are positional, not per-run).
//
// THE OUTPUT GOLDEN: the build flows' directory files are compared
// BYTE FOR BYTE — the frontmatter, the info callout, the taxonomy-
// ordered headings, the entry lines with their trims/joins, the sort
// keys (full lowercase: İ → i+U+0307, final sigma), the todo callout,
// and the closing regeneration line.
//
// THE LAW: goldens are never hand-edited; a divergence is either a Go
// bug (fix the port) or a reference behavior change (regenerate + say
// so in the commit).
package websitepipeline

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"

	"github.com/assadigit/second-brain-project/internal/constants"
	"github.com/assadigit/second-brain-project/internal/dryrun"
	"github.com/assadigit/second-brain-project/internal/links"
	"github.com/assadigit/second-brain-project/internal/taxonomy"
)

var dirgoldenRootRE = regexp.MustCompile(`^/tmp/dirgolden-[^/]+`)

// dirGolden is the decoded corpus for the directorynote golden.
var dirGolden map[string]any

func loadDirGolden(t *testing.T) map[string]any {
	t.Helper()
	if dirGolden != nil {
		return dirGolden
	}
	data, err := os.ReadFile("testdata/directorynote.golden.json")
	if err != nil {
		t.Fatalf("golden file: %v", err)
	}
	var g map[string]any
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatalf("golden json: %v", err)
	}
	dirGolden = g
	return g
}

func dirSection(t *testing.T, name string) map[string]any {
	t.Helper()
	g := loadDirGolden(t)
	v, ok := g[name].(map[string]any)
	if !ok {
		t.Fatalf("golden section %q missing or not an object", name)
	}
	return v
}

// cmpDirGolden byte-compares with both sides' tempdir roots folded to
// "<TMP>" (the generator's /tmp/dirgolden-XXXX and the Go test's
// t.TempDir()).
func cmpDirGolden(t *testing.T, what string, got, want any, root string) {
	t.Helper()
	cmpGoldenJSON(t, what, normPaths(normalizeGo(got), root), normPathsDir(want))
}

// normPathsDir folds the golden's baked tempdir root
// (/tmp/dirgolden-XXXX) to "<TMP>" — the golden's paths are positional
// facts, not per-run ones.
func normPathsDir(v any) any {
	repl := func(s string) string {
		return dirgoldenRootRE.ReplaceAllString(s, "<TMP>")
	}
	switch t := v.(type) {
	case map[string]any:
		out := map[string]any{}
		for k, val := range t {
			if s, ok := val.(string); ok {
				out[k] = repl(s)
			} else {
				out[k] = normPathsDir(val)
			}
		}
		return out
	case []any:
		out := make([]any, len(t))
		for i, val := range t {
			if s, ok := val.(string); ok {
				out[i] = repl(s)
			} else {
				out[i] = normPathsDir(val)
			}
		}
		return out
	}
	return v
}

// goldenLogs renders the captured log lines as [[level, msg], ...].
func goldenLogs(logs []logLine) []any {
	out := make([]any, 0, len(logs))
	for _, l := range logs {
		out = append(out, []any{l.level, l.msg})
	}
	return out
}

// sweepReportMap renders the report in the reference's dict shape.
func sweepReportMap(r SweepReport) map[string]any {
	moved := make([]any, 0, len(r.Moved))
	for _, m := range r.Moved {
		moved = append(moved, []any{m.URL, m.Src, m.Dst})
	}
	tables := make([]any, 0, len(r.MovedTables))
	for _, m := range r.MovedTables {
		tables = append(tables, []any{m.Platform, m.Src, m.Dst})
	}
	return map[string]any{
		"moved":            moved,
		"kept_handwritten": r.KeptHandwritten,
		"scanned":          r.Scanned,
		"moved_tables":     tables,
	}
}

// dirReportMap renders the report in the reference's dict shape (nil →
// null).
func dirReportMap(r *DirectoryReport) any {
	if r == nil {
		return nil
	}
	return map[string]any{
		"path":       r.Path,
		"sites":      r.Sites,
		"categories": r.Categories,
		"review":     r.Review,
	}
}

// dirNoteMap renders the parse in the reference's dict shape (nil →
// null).
func dirNoteMap(n *dirNote) any {
	if n == nil {
		return nil
	}
	return map[string]any{
		"app_owned":    n.appOwned,
		"source":       n.source,
		"category":     n.category,
		"subcategory":  n.subcategory,
		"pricing":      n.pricing,
		"fetch_status": n.fetchStatus,
		"tldr":         n.tldr,
		"title":        n.title,
	}
}

// listingOrNull mirrors the generator's listing(): sorted names, or
// null when the folder does not exist.
func listingOrNull(t *testing.T, path string) any {
	t.Helper()
	if _, err := os.Stat(path); os.IsNotExist(err) {
		return nil
	}
	return listDirT(t, path)
}

// --- the generator's fixture factories, Go-side ------------------------

// dnoteCustom mirrors the generator's note_text() exactly (every knob).
// An empty body appends nothing after the frontmatter (the read-cap
// case); the default body is dnoteDefaultBody.
func dnoteCustom(url, category, subcategory, pricing, title, tldr string,
	managed bool, fetchStatus string, extraFM []string, body string) string {
	managedBy := "gitcurator"
	if !managed {
		managedBy = "human"
	}
	fm := []string{
		"---",
		fmt.Sprintf("source: \"%s\"", url),
		"aliases: []",
		"tags: []",
		fmt.Sprintf("category: \"%s\"", category),
		fmt.Sprintf("subcategory: \"%s\"", subcategory),
		fmt.Sprintf("fetch_status: \"%s\"", fetchStatus),
		fmt.Sprintf("pricing: \"%s\"", pricing),
		`login_required: "unknown"`,
		"date_processed: 2026-10-01",
		fmt.Sprintf("managed_by: \"%s\"", managedBy),
		`schema_version: "1"`,
		`prompt_version: "web-v2"`,
	}
	fm = append(fm, extraFM...)
	fm = append(fm, "---")
	if body == "" {
		return strings.Join(fm, "\n")
	}
	return strings.Join(fm, "\n") + body
}

func dnoteDefaultBody(url, title, tldr string) string {
	return fmt.Sprintf("\n\n> [!info] Managed by GitCurator — machine-written note.\n\n# %s\n\n> **TL;DR:** %s\n\n## Best used for\nUse when you need to…\n\n## Similar tools\n—\n\n---\n*Source: [%s](%s)*\n",
		title, tldr, url, url)
}

// dnote is note_text() with its defaults.
func dnote(url, category, subcategory, pricing, title, tldr string, managed bool, fetchStatus string) string {
	return dnoteCustom(url, category, subcategory, pricing, title, tldr, managed, fetchStatus, nil,
		dnoteDefaultBody(url, title, tldr))
}

// dvn writes one note (the generator's vn()) into a vault by rel path.
func dvn(t *testing.T, vault, rel, url, category, subcategory, pricing, title, tldr string, managed bool, fetchStatus string) {
	t.Helper()
	path := filepath.Join(vault, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(dnote(url, category, subcategory, pricing, title, tldr, managed, fetchStatus)), 0o644); err != nil {
		t.Fatal(err)
	}
}

// gwriteB writes raw bytes (the generator's writeb()).
func gwriteB(t *testing.T, path string, data []byte) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, data, 0o644); err != nil {
		t.Fatal(err)
	}
}

// gwriteT writes raw text with NO newline translation (the
// generator's write(newline="")).
func gwriteT(t *testing.T, path, text string) {
	t.Helper()
	gwriteB(t, path, []byte(text))
}

// dtables writes the generator's tables_vault(): the nine _inbox
// platform tables.
func dtables(t *testing.T, vault string) {
	t.Helper()
	inbox := filepath.Join(vault, "_inbox")
	if err := os.MkdirAll(inbox, 0o755); err != nil {
		t.Fatal(err)
	}
	for _, fname := range []string{"x_twitter_links.md", "youtube_links.md",
		"linkedin_links.md", "huggingface_links.md", "reddit_links.md",
		"medium_links.md", "arxiv_links.md", "package_registry_links.md",
		"other_links.md"} {
		stem := strings.SplitN(fname, "_", 2)[0]
		content := fmt.Sprintf("# %s\n\n| - | 2026-10-05 | https://%s.example/x | x | Bot | unreviewed | |\n", fname, stem)
		gwriteT(t, filepath.Join(inbox, fname), content)
	}
}

// dLaw is the generator's LAW: the reference's full blocked-domain law.
func dLaw() []string {
	return links.BlockedDomainsFromConfig(map[string]any{})
}

// loadGoldenTaxonomies writes the golden's two taxonomy SOURCES to temp
// files and parses them (the Go replay reconstructs both sides' inputs
// from the same baked bytes).
func loadGoldenTaxonomies(t *testing.T) (synth, real *taxonomy.Taxonomy, synthPath string) {
	t.Helper()
	g := dirSection(t, "taxonomy")
	tmp := t.TempDir()
	synthPath = filepath.Join(tmp, "synthetic-taxonomy.md")
	gwriteT(t, synthPath, gstr(t, g, "synthetic_source"))
	realPath := filepath.Join(tmp, "real-taxonomy.md")
	gwriteT(t, realPath, gstr(t, g, "real_source"))
	var err error
	synth, err = taxonomy.LoadTaxonomy(synthPath)
	if err != nil {
		t.Fatalf("synthetic taxonomy: %v", err)
	}
	real, err = taxonomy.LoadTaxonomy(realPath)
	if err != nil {
		t.Fatalf("real taxonomy: %v", err)
	}
	return synth, real, synthPath
}

// taxShape mirrors the generator's tax_shape(): [[name, [subs]], ...].
func taxShape(tax *taxonomy.Taxonomy) []any {
	out := make([]any, 0)
	for _, c := range tax.Categories() {
		subs := make([]any, 0, len(c.Subcategories))
		for _, s := range c.Subcategories {
			subs = append(subs, s)
		}
		out = append(out, []any{c.Name, subs})
	}
	return out
}

// sortedSkipNames renders a skip set as the golden's sorted list.
func sortedSkipNames(m map[string]bool) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

