func TestDirectoryGoldenParseNote(t *testing.T) {
	want := dirSection(t, "parse_note")
	dir := filepath.Join(t.TempDir(), "parse")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	type caseSpec struct {
		name  string
		write func(path string)
	}
	defBody := func(body string) func(string) {
		return func(path string) {
			gwriteT(t, path, dnoteCustom("https://example.com/", "Design", "Assets & Resources", "free", "Test Site", "A test page.", true, "full", nil, body))
		}
	}
	cases := []caseSpec{
		{"canonical.md", func(p string) {
			gwriteT(t, p, dnote("https://example.com/", "Design", "Assets & Resources", "free", "Test Site", "A test page.", true, "full"))
		}},
		{"no_frontmatter.md", func(p string) { gwriteT(t, p, "Just a body, no frontmatter at all.\n") }},
		{"fm_no_close.md", func(p string) { gwriteT(t, p, "---\nsource: \"https://x.example/\"\nbody without a closing fence\n") }},
		{"newline_first.md", func(p string) { gwriteT(t, p, "\n---\nsource: \"https://x.example/\"\n---\nbody\n") }},
		{"empty.md", func(p string) { gwriteT(t, p, "") }},
		{"only_openers.md", func(p string) { gwriteT(t, p, "---\n---\n# Just A Heading\n") }},
		{"dashes_only.md", func(p string) { gwriteT(t, p, "---\n---\n---\nbody\n") }},
		{"quoted.md", func(p string) {
			gwriteT(t, p, "---\nsource: 'https://single.example/'\ncategory: \"Double Quoted\"\nsubcategory: no_quotes_here\npricing: 'mixed'\n---\n# T\n")
		}},
		{"dashed_key.md", func(p string) { gwriteT(t, p, "---\nsome-key: ignored\ncategory: Design\n---\n# T\n") }},
		{"dup_keys.md", func(p string) { gwriteT(t, p, "---\ncategory: First\ncategory: Second\n---\n# T\n") }},
		{"unicode_ws.md", func(p string) { gwriteT(t, p, "---\npricing: free\u00a0\ncategory: A\u00a0B\n---\n# T\n") }},
		{"no_colon.md", func(p string) { gwriteT(t, p, "---\njust a line\ncategory: Design\n---\n# T\n") }},
		{"empty_value.md", func(p string) { gwriteT(t, p, "---\nsource:\ncategory: Design\n---\n# T\n") }},
		{"tldr_emdash.md", defBody("") /* replaced below */},
	}
	// the em-dash/hyphen cases carry a full default note with a special
	// TL;DR — build them explicitly.
	cases = append(cases[:len(cases)-1],
		caseSpec{"tldr_emdash.md", func(p string) {
			gwriteT(t, p, dnote("https://example.com/", "Design", "Assets & Resources", "free", "Test Site", "—", true, "full"))
		}},
		caseSpec{"tldr_hyphen.md", func(p string) {
			gwriteT(t, p, dnote("https://example.com/", "Design", "Assets & Resources", "free", "Test Site", "-", true, "full"))
		}},
		caseSpec{"tldr_missing.md", defBody("\n\n# Title Only\n\nNo TL;DR here.\n")},
		caseSpec{"tldr_ws_only.md", defBody("\n\n# T\n\n> **TL;DR:** \u2002\n\nmore\n")},
		caseSpec{"tldr_first_wins.md", defBody("\n\n# T\n\n> **TL;DR:** first\n\n> **TL;DR:** second\n")},
		caseSpec{"tldr_indent.md", defBody("\n\n# T\n\n>  **TL;DR:** two spaces after the quote\n")},
		caseSpec{"h1_no_space.md", defBody("\n\n#NoSpace\n\n> **TL;DR:** x\n")},
		caseSpec{"h1_h2.md", defBody("\n\n## Not H1\n\n# Real H1\n\n> **TL;DR:** x\n")},
		caseSpec{"rule_line.md", func(p string) {
			gwriteT(t, p, "---\nsource: \"https://rules.example/\"\ncategory: Design\n---\n\n# Rule Note\n\n> **TL;DR:** rules\n\n---\nmid rule\n\n---\n*Source: [x](y)*\n")
		}},
		caseSpec{"invalid_utf8.md", func(p string) {
			gwriteB(t, p, []byte("---\nsource: \"https://bad.example/\xe2\x82\"\ncategory: Bad\xff\n---\n\n# Bad \xfeBytes\n\n> **TL;DR:** invalid\n"))
		}},
		caseSpec{"read_cap.md", func(p string) {
			head := dnoteCustom("https://big.example/", "Design", "Assets & Resources", "free", "Test Site", "A test page.", true, "full", nil, "")
			gwriteT(t, p, head+"\n\n# Early Heading\n\n"+strings.Repeat("x", 600_000)+"\n\n> **TL;DR:** beyond the cap\n")
		}},
		caseSpec{"crlf.md", func(p string) {
			gwriteT(t, p, strings.ReplaceAll(dnote("https://example.com/", "Design", "Assets & Resources", "free", "Test Site", "A test page.", true, "full"), "\n", "\r\n"))
		}},
		caseSpec{"cr_only.md", func(p string) {
			gwriteT(t, p, strings.ReplaceAll(dnote("https://example.com/", "Design", "Assets & Resources", "free", "Test Site", "A test page.", true, "full"), "\n", "\r"))
		}},
	)
	got := map[string]any{}
	for _, c := range cases {
		p := filepath.Join(dir, c.name)
		c.write(p)
		got[c.name] = dirNoteMap(parseDirNote(p))
	}
	got["missing_file"] = dirNoteMap(parseDirNote(filepath.Join(t.TempDir(), "gone.md")))
	cmpDirGolden(t, "parse_note", got, want, "")
}

func TestDirectoryGoldenIterWalk(t *testing.T) {
	want := dirSection(t, "iter_walk")
	w := filepath.Join(t.TempDir(), "walktree")
	type wf struct {
		rel string
		url string
	}
	files := []wf{
		{"zNote.md", "https://z.example/"},
		{"m-note.md", "https://m.example/"},
		{"a-dir/inner.md", "https://i.example/"},
		{"a-dir/z-inner.md", "https://zi.example/"},
		{"b-dir/n1.md", "https://n1.example/"},
		{"b-dir/N2.MD", "https://n2.example/"},
		{"_review/r.md", "https://r.example/"},
		{"_missing/m.md", "https://mi.example/"},
		{"_moc/m.md", "https://moc.example/"},
		{"attachments/a.md", "https://att.example/"},
		{"_inbox/i.md", "https://in.example/"},
		{".obsidian/o.md", "https://ob.example/"},
		{".trash/t.md", "https://t.example/"},
		{".git/g.md", "https://g.example/"},
		{DirectoryFilename, "https://dir.example/"},
		{".hidden.md", "https://hid.example/"},
		{"sub/_inbox/deep.md", "https://deep.example/"},
		{"sub/deep.md", "https://sdeep.example/"},
	}
	for _, f := range files {
		p := filepath.Join(w, filepath.FromSlash(f.rel))
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, []byte(dnote(f.url, "Design", "Assets & Resources", "free", "Test Site", "A test page.", true, "full")), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	if err := os.Symlink(filepath.Join(w, "zNote.md"), filepath.Join(w, "link-file.md")); err != nil {
		t.Skipf("symlinks unavailable: %v", err)
	}
	if err := os.Symlink(filepath.Join(w, "a-dir"), filepath.Join(w, "dirlink.md")); err != nil {
		t.Skipf("symlinks unavailable: %v", err)
	}
	collect := func(forSweep bool) []string {
		var out []string
		iterNoteFiles(w, forSweep, func(path string) {
			rel, err := filepath.Rel(w, path)
			if err != nil {
				t.Fatal(err)
			}
			out = append(out, filepath.ToSlash(rel))
		})
		return out
	}
	got := map[string]any{
		"directory": collect(false),
		"sweep":     collect(true),
	}
	cmpDirGolden(t, "iter_walk", got, want, "")
}

