func TestDirectoryGoldenTrimAliasCategoryOrder(t *testing.T) {
	synth, _, _ := loadGoldenTaxonomies(t)
	trimWant := loadDirGolden(t)["trim"].([]any)
	for i, item := range trimWant {
		triple := item.([]any)
		text := triple[0].(string)
		limit := int(triple[1].(float64))
		got := []any{text, limit, trimRunes(text, limit)}
		cmpDirGolden(t, fmt.Sprintf("trim[%d]", i), got, triple, "")
	}
	aliasWant := loadDirGolden(t)["alias_safe"].([]any)
	for i, item := range aliasWant {
		pair := item.([]any)
		title := pair[0].(string)
		got := []any{title, aliasSafe(title)}
		cmpDirGolden(t, fmt.Sprintf("alias_safe[%d]", i), got, pair, "")
	}
	want := dirSection(t, "category_order")
	got := map[string]any{
		"with_taxonomy": categoryOrder(map[string]bool{
			"Zeta Cat": true, "Alpha Cat": true, "Leftover B": true,
			"Leftover A": true, "Middle Cat": true,
		}, synth),
		"no_taxonomy": categoryOrder(map[string]bool{
			"Beta": true, "Alpha": true, "Gamma": true,
		}, nil),
		"empty_name_excluded": categoryOrder(map[string]bool{
			"": true, "Named": true,
		}, synth),
	}
	cmpDirGolden(t, "category_order", got, want, "")
}

// --- the sweep flows ----------------------------------------------------

func TestDirectoryGoldenSweepFlows(t *testing.T) {
	dryrun.Disable()
	dryrun.Clear()
	t.Cleanup(func() {
		dryrun.Disable()
		dryrun.Clear()
	})
	tmp := t.TempDir()

	run := func(name string, seed func(vault string), blocked []string) (SweepReport, []logLine, string) {
		vault := filepath.Join(tmp, name)
		if err := os.MkdirAll(vault, 0o755); err != nil {
			t.Fatal(err)
		}
		seed(vault)
		var logs []logLine
		report := SweepBannedNotes(vault, blocked, func(msg, level string) {
			logs = append(logs, logLine{level: level, msg: msg})
		})
		return report, logs, vault
	}

	// legacy_pile
	report, logs, vault := run("sweep-legacy_pile", func(v string) {
		for i, sid := range []string{"2011934783064826", "2011943712111707", "2011947543668256"} {
			dvn(t, v, fmt.Sprintf("_review/x_com_i_status_%s.md", sid),
				fmt.Sprintf("https://x.com/i/status/%s", sid), "", "", "unknown",
				fmt.Sprintf("tweet %d", i), "", true, "failed")
		}
		dvn(t, v, "Design/Assets_Resources/Real_Site.md", "https://reverseui.com/",
			"", "", "unknown", "Real Site", "", true, "full")
	}, dLaw())
	got := map[string]any{
		"report":      sweepReportMap(report),
		"logs":        goldenLogs(logs),
		"quarantine":  listingOrNull(t, filepath.Join(vault, ".trash", "banned-domains")),
		"review_left": listDirT(t, filepath.Join(vault, "_review")),
		"design_left": listDirT(t, filepath.Join(vault, "Design", "Assets_Resources")),
	}
	cmpDirGolden(t, "sweep_legacy_pile", got, dirSection(t, "sweep_legacy_pile"), tmp)

	// real_notes
	report, logs, vault = run("sweep-real_notes", func(v string) {
		dvn(t, v, "Design/Tools/tco_note.md", "https://t.co/abc", "", "", "free", "x", "", true, "full")
		dvn(t, v, "AI_Tools_(General)/hf_note.md", "https://huggingface.co/org/model", "", "", "free", "x", "", true, "full")
		dvn(t, v, "Random__Curiosities/ig_note.md", "https://www.instagram.com/p/xyz/", "", "", "free", "x", "", true, "full")
	}, dLaw())
	got = map[string]any{
		"report":     sweepReportMap(report),
		"logs":       goldenLogs(logs),
		"quarantine": listingOrNull(t, filepath.Join(vault, ".trash", "banned-domains")),
		"left":       allFilesSorted(t, vault),
	}
	cmpDirGolden(t, "sweep_real_notes", got, dirSection(t, "sweep_real_notes"), tmp)

	// handwritten
	report, logs, vault = run("sweep-handwritten", func(v string) {
		dvn(t, v, "Notes/my_own_x_thread.md", "https://x.com/thread", "", "", "free", "My notes", "", false, "full")
		dvn(t, v, "Design/Real.md", "https://real.example/", "", "", "free", "Real", "", true, "full")
	}, dLaw())
	got = map[string]any{
		"report":     sweepReportMap(report),
		"logs":       goldenLogs(logs),
		"quarantine": listingOrNull(t, filepath.Join(vault, ".trash", "banned-domains")),
		"notes_left": listDirT(t, filepath.Join(vault, "Notes")),
	}
	cmpDirGolden(t, "sweep_handwritten", got, dirSection(t, "sweep_handwritten"), tmp)

	// platform_tables
	report, logs, vault = run("sweep-platform_tables", func(v string) {
		dtables(t, v)
	}, dLaw())
	got = map[string]any{
		"report":     sweepReportMap(report),
		"logs":       goldenLogs(logs),
		"quarantine": listingOrNull(t, filepath.Join(vault, ".trash", "banned-domains")),
		"inbox_left": listDirT(t, filepath.Join(vault, "_inbox")),
	}
	cmpDirGolden(t, "sweep_platform_tables", got, dirSection(t, "sweep_platform_tables"), tmp)

	// partial_ban (dotted/upper/padded entries normalize)
	report, logs, vault = run("sweep-partial_ban", func(v string) {
		dtables(t, v)
	}, []string{" x.com ", ".T.CO", "twitter.com", "youtube.com"})
	got = map[string]any{
		"report":     sweepReportMap(report),
		"logs":       goldenLogs(logs),
		"quarantine": listingOrNull(t, filepath.Join(vault, ".trash", "banned-domains")),
		"inbox_left": listDirT(t, filepath.Join(vault, "_inbox")),
	}
	cmpDirGolden(t, "sweep_partial_ban", got, dirSection(t, "sweep_partial_ban"), tmp)

	// order_pin (the insertion order of moved_tables)
	report, logs, vault = run("sweep-order_pin", func(v string) {
		dtables(t, v)
	}, append(dLaw(), "arxiv.org", "npmjs.com", "pypi.org"))
	got = map[string]any{
		"report":     sweepReportMap(report),
		"logs":       goldenLogs(logs),
		"quarantine": listingOrNull(t, filepath.Join(vault, ".trash", "banned-domains")),
	}
	cmpDirGolden(t, "sweep_order_pin", got, dirSection(t, "sweep_order_pin"), tmp)

	// collision
	report, logs, vault = run("sweep-collision", func(v string) {
		dvn(t, v, "_review/x_com_1.md", "https://x.com/1", "", "", "free", "x", "", true, "full")
		dvn(t, v, "Design/x_com_1.md", "https://x.com/1b", "", "", "free", "x", "", true, "full")
	}, dLaw())
	got = map[string]any{
		"report":     sweepReportMap(report),
		"logs":       goldenLogs(logs),
		"quarantine": listingOrNull(t, filepath.Join(vault, ".trash", "banned-domains")),
	}
	cmpDirGolden(t, "sweep_collision", got, dirSection(t, "sweep_collision"), tmp)

	// twice (idempotence)
	vault = filepath.Join(tmp, "sweep-twice")
	if err := os.MkdirAll(vault, 0o755); err != nil {
		t.Fatal(err)
	}
	dvn(t, vault, "_review/x_com_1.md", "https://x.com/1", "", "", "free", "x", "", true, "full")
	var logs1 []logLine
	rep1 := SweepBannedNotes(vault, dLaw(), func(msg, level string) {
		logs1 = append(logs1, logLine{level: level, msg: msg})
	})
	var logs2 []logLine
	rep2 := SweepBannedNotes(vault, dLaw(), func(msg, level string) {
		logs2 = append(logs2, logLine{level: level, msg: msg})
	})
	got = map[string]any{
		"first": map[string]any{
			"report":     sweepReportMap(rep1),
			"logs":       goldenLogs(logs1),
			"quarantine": listingOrNull(t, filepath.Join(vault, ".trash", "banned-domains")),
		},
		"second_report": sweepReportMap(rep2),
		"second_logs":   goldenLogs(logs2),
		"quarantine":    listingOrNull(t, filepath.Join(vault, ".trash", "banned-domains")),
	}
	cmpDirGolden(t, "sweep_twice", got, dirSection(t, "sweep_twice"), tmp)

	// empty_blocked
	report, logs, vault = run("sweep-empty_blocked", func(v string) {
		dvn(t, v, "_review/x_com_1.md", "https://x.com/1", "", "", "free", "x", "", true, "full")
	}, nil)
	got = map[string]any{
		"report":     sweepReportMap(report),
		"logs":       goldenLogs(logs),
		"quarantine": listingOrNull(t, filepath.Join(vault, ".trash", "banned-domains")),
		"file_kept":  fileExistsT(t, filepath.Join(vault, "_review", "x_com_1.md")),
	}
	cmpDirGolden(t, "sweep_empty_blocked", got, dirSection(t, "sweep_empty_blocked"), tmp)

	// missing vault
	var logsM []logLine
	repM := SweepBannedNotes(filepath.Join(tmp, "nope-missing-vault"), dLaw(), func(msg, level string) {
		logsM = append(logsM, logLine{level: level, msg: msg})
	})
	got = map[string]any{
		"report":     sweepReportMap(repM),
		"logs":       goldenLogs(logsM),
		"quarantine": nil,
	}
	cmpDirGolden(t, "sweep_missing_vault", got, dirSection(t, "sweep_missing_vault"), tmp)

	// scanned (the counter)
	report, logs, vault = run("sweep-scanned", func(v string) {
		dvn(t, v, "plain.md", "https://plain.example/", "", "", "free", "Test Site", "A test page.", true, "full")
		gwriteT(t, filepath.Join(v, "no-fm.md"), "no frontmatter\n")
		gwriteT(t, filepath.Join(v, "no-source.md"), "---\ncategory: Design\nmanaged_by: \"gitcurator\"\n---\n\n# No Source\n\nbody\n")
		dvn(t, v, "hand.md", "https://x.com/h", "", "", "free", "Test Site", "A test page.", false, "full")
		gwriteT(t, filepath.Join(v, "notes.txt"), "not a note\n")
	}, dLaw())
	got = map[string]any{
		"report":     sweepReportMap(report),
		"logs":       goldenLogs(logs),
		"quarantine": listingOrNull(t, filepath.Join(vault, ".trash", "banned-domains")),
	}
	cmpDirGolden(t, "sweep_scanned", got, dirSection(t, "sweep_scanned"), tmp)

	// dry-run (records, never performs)
	vault = filepath.Join(tmp, "sweep-dryrun")
	if err := os.MkdirAll(vault, 0o755); err != nil {
		t.Fatal(err)
	}
	dvn(t, vault, "_review/x_com_1.md", "https://x.com/1", "", "", "free", "x", "", true, "full")
	dtables(t, vault)
	dryrun.Enable()
	dryrun.Clear()
	var logsD []logLine
	repD := SweepBannedNotes(vault, dLaw(), func(msg, level string) {
		logsD = append(logsD, logLine{level: level, msg: msg})
	})
	dryrun.Disable()
	dryrun.Clear()
	got = map[string]any{
		"report":     sweepReportMap(repD),
		"logs":       goldenLogs(logsD),
		"quarantine": listingOrNull(t, filepath.Join(vault, ".trash", "banned-domains")),
		"file_kept":  fileExistsT(t, filepath.Join(vault, "_review", "x_com_1.md")),
		"table_kept": fileExistsT(t, filepath.Join(vault, "_inbox", "x_twitter_links.md")),
	}
	cmpDirGolden(t, "sweep_dryrun", got, dirSection(t, "sweep_dryrun"), tmp)
}

// allFilesSorted mirrors the generator's sweep_real_notes "left" dump:
// every file under the vault, sorted relpaths.
func allFilesSorted(t *testing.T, vault string) []string {
	t.Helper()
	var out []string
	err := filepath.WalkDir(vault, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		rel, relErr := filepath.Rel(vault, path)
		if relErr != nil {
			return relErr
		}
		out = append(out, filepath.ToSlash(rel))
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	sort.Strings(out)
	return out
}

func fileExistsT(t *testing.T, path string) bool {
	t.Helper()
	_, err := os.Stat(path)
	return err == nil
}

