		dvn(t, v, "Middle/MiddleOne.md", "https://middleone.example/", "Middle Cat", "Assets & Resources", "free", "Middle Note", "No subcategories in taxonomy", true, "full")
		dvn(t, v, "Leftovers/LeftoverCat.md", "https://leftcat.example/", "Leftover Category", "Assets & Resources", "free", "Leftover Cat Note", "Not in the taxonomy at all", true, "full")
		dvn(t, v, "Uncat/NoCat.md", "https://nocat.example/", "", "Assets & Resources", "free", "No Category Given", "Falls back to Uncategorized", true, "full")
