		dvn(t, v, "Trims/LongTldr.md", "https://longtldr.example/", "Zeta Cat", "Sub Two", "free", "Long TLDR", strings.Repeat("word ", 60), true, "full")
		dvn(t, v, "Trims/LongTitle.md", "https://longtitle.example/", "Zeta Cat", "Sub Two", "free", "A Very Long Title Indeed "+strings.Repeat("x", 90), "The alias cap applies", true, "full")
		dvn(t, v, "Trims/AliasChars.md", "https://aliaschars.example/", "Zeta Cat", "Sub Two", "free", "[Wiki] | Broken^#Alias", "Alias chars stripped", true, "full")
		gwriteT(t, filepath.Join(v, "Trims", "NoTldr.md"), dnoteCustom("https://notldr.example/", "Zeta Cat", "Sub Two", "free", "No TLDR Note", "", true, "full", nil, "\n\n# No TLDR Note\n\n## Best used for\nx\n"))
